const CHARACTERS={wanderer:{id:'wanderer',name:'灰の放浪者',hp:70,icon:'♜',theme:'灰と契約',desc:'当てもなく彷徨う旅人。各地を巡る彼は、様々な土地の戦闘技術を身につけ、あらゆる状況に対応できる。\n攻守ともに優れており、刃の通らない敵は毒で蝕む。'},hunter:{id:'hunter',name:'獣の狩人',hp:80,icon:'♞',theme:'進化と狩猟',desc:'獣の力をその身に宿す狩人。狩りのスペシャリストである彼に仕留められない獲物はいない。\n裂傷や脆弱で敵を追い詰め、進化する力で確実にその命を刈り取る。'}};
CHARACTERS.lucky={id:'lucky',name:'ラッキー・ガール',hp:77,icon:'♧',theme:'仕込みと勝負',desc:'勝利の女神は彼女に微笑んでいる。あらゆる賭け事において、彼女は負ける事を知らない。\n様々な『勝負』に勝つことで高いパフォーマンスを発揮する。勝負に勝つには「仕込み」が重要である。'};
let startingCharacterId=null,characterStartConfirmed=false;
function currentCharacterId(r=S.run){return r?.characterId||startingCharacterId||S.selectedCharacter||'wanderer';}
function selectedCharacter(){return CHARACTERS[currentCharacterId()]||CHARACTERS.wanderer;}
function storeCharacterProfile(){if(!S.characterProfiles)return;let id=S.selectedCharacter||'wanderer';S.characterProfiles[id]={deck:[...S.deck],deckSets:JSON.parse(JSON.stringify(S.deckSets)),deckSetMeta:JSON.parse(JSON.stringify(S.deckSetMeta))};}
function initializeCharacters(){S.selectedCharacter=CHARACTERS[S.selectedCharacter]?S.selectedCharacter:'wanderer';S.characterProfiles??={};const snapshot={deck:[...S.deck],deckSets:JSON.parse(JSON.stringify(S.deckSets||Array(5).fill(null))),deckSetMeta:JSON.parse(JSON.stringify(S.deckSetMeta||Array.from({length:5},(_,i)=>({name:'マイセット '+(i+1),relicId:null}))))};S.characterProfiles[S.selectedCharacter]??=snapshot;for(const id of Object.keys(CHARACTERS))S.characterProfiles[id]??={deck:[...snapshot.deck],deckSets:Array(5).fill(null),deckSetMeta:Array.from({length:5},(_,i)=>({name:'マイセット '+(i+1),relicId:null}))};if(S.run)S.run.characterId??='wanderer';}
initializeCharacters();
function selectCharacter(id){if(S.run||!CHARACTERS[id])return;storeCharacterProfile();S.selectedCharacter=id;const p=S.characterProfiles[id];S.deck=[...p.deck];S.deckSets=JSON.parse(JSON.stringify(p.deckSets));S.deckSetMeta=JSON.parse(JSON.stringify(p.deckSetMeta));deckResetPending=false;render();}
const saveCharacterBase=save;save=function(){if(globalThis.ASHBOUND_LOADING)return;storeCharacterProfile();saveCharacterBase();};
const allowedCharacterBase=allowedRunCard;allowedRunCard=function(c,r=S.run){return !!c&&allowedCharacterBase(c,r)&&!c.evolution&&!c.token&&(c.characterId||'wanderer')===currentCharacterId(r);};
const startCharacterBase=start;start=function(){if(S.run)return;if(!characterStartConfirmed&&!globalThis.ASHBOUND_HEADLESS){page='characters';render();return;}startingCharacterId=S.selectedCharacter;try{startCharacterBase();if(S.run){S.run.characterId=startingCharacterId;const max=CHARACTERS[startingCharacterId].hp;S.run.max=hasRelic('energy_hp',S.run)?Math.floor(max*.8):max;S.run.hp=S.run.max;render();}}finally{startingCharacterId=null;characterStartConfirmed=false;}};
function startSelectedCharacter(){characterStartConfirmed=true;try{start();}finally{characterStartConfirmed=false;}}
let characterCodexReturn=false;
function viewCharacterPotentials(){if(S.run)return;codexCharacterId=S.selectedCharacter;resetCodexFilters();bookType='run';page='book';characterCodexReturn=true;render();}
function returnFromCharacterCodex(){const destination=characterCodexReturn&&!S.run?'characters':S.run?S.run.mode:'home';characterCodexReturn=false;go(destination);}
function explorerDeckOverview(){return [...new Set(S.deck)].sort(cardOrder).map(id=>`<div class="explorer-card-slot" data-card-id="${id}" data-quantity="${count(id)}">${card(id,`inspectExplorerCard(${id})`,`<span class="count">デッキ内 ×${count(id)}</span>`)}</div>`).join('')||'<p>基礎デッキが空です。</p>';}
function inspectExplorerCard(id){if(S.run||page!=='characters'||!S.deck.includes(id))return;document.getElementById('explorer-card-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='explorer-card-dialog';dialog.setAttribute('aria-label',C[id].name+'の詳細');dialog.innerHTML=`<form method="dialog"><button class="explorer-card-close">閉じる</button></form>${card(id)}`;dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal();}
function characterSelection(){const c=CHARACTERS[S.selectedCharacter],skill=explorationSkillFor(c.id);return `<section class="character-selection explorer-selection"><div class="section-head"><div><div class="eyebrow">CHOOSE YOUR PATH</div><h1>探索者を選ぶ</h1></div><button onclick="go('home')">拠点へ戻る</button></div><div class="explorer-layout"><div class="explorer-portrait" aria-label="${c.name}"><span aria-hidden="true">${c.icon}</span><h2>${c.name}</h2><p>${c.theme}</p></div><div class="explorer-details"><section class="explorer-vitals" aria-label="能力"><div class="explorer-hp"><span>HP</span><strong>${c.hp}</strong></div>${skill?`<div class="explorer-skill"><span>探索技能</span><h3>${skill.name}</h3><p>${skill.desc}</p></div>`:''}<button onclick="viewCharacterPotentials()">潜在カードを閲覧</button></section><section class="character-loadout explorer-deck"><div class="section-head"><div><div class="eyebrow">CURRENT LOADOUT</div><h3>現在のデッキ <small>${S.deck.length}枚</small></h3></div><button onclick="showExplorerDeckList()">デッキ一覧</button><button onclick="go('deck')">デッキ・マイセットを編集</button></div><div class="cards explorer-deck-cards">${explorerDeckOverview()}</div></section><section class="explorer-story"><h3>${c.name}</h3>${c.desc.split('\n').map(p=>`<p>${p}</p>`).join('')}</section><div class="explorer-depart"><p>${S.deck.length<10?'出発には基礎デッキが10枚以上必要です。':'基礎カードと遺物は共通。デッキとマイセットは探索者ごとに保存。'}</p></div></div></div><div class="character-options explorer-roster" role="group" aria-label="探索者を選択">${Object.values(CHARACTERS).map(x=>`<button class="character-option explorer-roster-card ${x.id===c.id?'selected':''}" aria-pressed="${x.id===c.id}" onclick="selectCharacter('${x.id}')"><span class="character-sigil" aria-hidden="true">${x.icon}</span><strong>${x.name}</strong><small>${x.id===c.id?'選択中':'選択する'}</small></button>`).join('')}</div></section>`;}
const homeCharacterBase=home;home=function(){return homeCharacterBase().replace(/灰の契約者/g,'灰の放浪者').replace('廃都へ出発','探索者を選んで出発');};
const deckCharacterBase=deck;deck=function(){const html=deckCharacterBase();if(S.run)return html;return `<div class="character-deck-bar"><strong>${selectedCharacter().icon} ${selectedCharacter().name} の基礎デッキ</strong><button onclick="page='characters';render()">探索者を変更</button></div>`+html;};
const bookCharacterBase=book;book=function(){if(bookType!=='run')return bookCharacterBase();const character=selectedCharacter(),pool=C.filter(c=>c.runOnly&&!c.retired&&!c.outsideCardPool&&c.characterId===character.id);return `<div class="eyebrow">CHARACTER CODEX</div><h2>${character.name}の潜在カード</h2><div class="toolbar"><button onclick="bookType='base';render()">基礎カード</button><button class="primary">潜在カード</button><button onclick="bookType='relics';render()">遺物</button><button onclick="go(S.run?S.run.mode:'characters')">戻る →</button></div><p>進化カードは戦闘中の進化でのみ使用できます。報酬・パック・生成では入手できません。</p><div class="cards">${pool.filter(c=>!c.evolution).map(c=>card(c.id)).join('')}</div>${pool.some(c=>c.evolution)?`<h3>進化カード</h3><div class="cards">${pool.filter(c=>c.evolution).map(c=>card(c.id)).join('')}</div>`:''}`;};
const renderCharacterBase=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;renderCharacterBase();if(page==='characters'&&!S.run)$('app').innerHTML=characterSelection();if(!S.run)$('nav').innerHTML+=`<button class="${page==='characters'?'active':''}" onclick="page='characters';render()">探索者</button>`;save();};

function characterRunPacks(r){return RUN_PACKS;}
